import React from 'react';
import './Register.css';
import heartImg from '../../assets/heart.png'; 
import logo from '../../assets/Logo.png';
import { FaUser, FaEnvelope, FaLock, FaIdCard } from 'react-icons/fa';

const Register = () => {
  return (
    <div className="register-container d-flex">

      {/* Left Side */}
      <div
        className="left-side flex-fill d-flex flex-column align-items-center justify-content-center"
        style={{
          backgroundImage: `linear-gradient(rgba(0,0,0,0.25), rgba(0,0,0,0.25)), url(${heartImg})`,
        }}
      >
        <div className="logo-title-wrapper d-flex align-items-center justify-content-center">
          <img src={logo} alt="logo" className="logo me-3" />
          <div className="heart-title text-center">Heart Diseases</div>
        </div>
      </div>

      {/* Right Side */}
      <div className="right-side flex-fill d-flex justify-content-center align-items-center position-relative">
        <div className="register-content w-75 d-flex flex-column align-items-center">
          <h2 className="text-center mb-4">Register Page</h2>

          <div className="input-group mb-3 position-relative">
            <input type="email" className="form-control rounded-pill ps-4" placeholder="Email" />
            <FaEnvelope className="input-icon position-absolute end-0 top-50 translate-middle-y me-3" />
          </div>

          <div className="input-group mb-3 position-relative">
            <input type="text" className="form-control rounded-pill ps-4" placeholder="National ID" />
            <FaIdCard className="input-icon position-absolute end-0 top-50 translate-middle-y me-3" />
          </div>

          <div className="input-group mb-3 position-relative">
            <input type="text" className="form-control rounded-pill ps-4" placeholder="Username" />
            <FaUser className="input-icon position-absolute end-0 top-50 translate-middle-y me-3" />
          </div>

          <div className="input-group mb-4 position-relative">
            <input type="password" className="form-control rounded-pill ps-4" placeholder="Password" />
            <FaLock className="input-icon position-absolute end-0 top-50 translate-middle-y me-3" />
          </div>

          <button className="btn btn-primary w-100 rounded-pill mb-3">Create Account</button>

          <div className="login-link text-center">
            Already have an account? <a href="/login">Login</a>
          </div>
        </div>

        {/* Shadows */}
        <div className="position-absolute top-0 end-0 w-100 h-100" style={{ pointerEvents: 'none' }}>
          <div className="shadow-top-end"></div>
          <div className="shadow-bottom-start"></div>
        </div>
      </div>
    </div>
  );
};

export default Register;
